  legalServiceTitle: '2. وصف الخدمة',
  legalServiceDesc: 'HireNova هي خدمة إنشاء سير ذاتية ورسائل تغطية مدعومة بالذكاء الاصطناعي عبر الإنترنت، متاحة بـ 4 لغات (الفرنسية والإنجليزية والعربية والإسبانية) مع 3 قوالب تصميم و2 صيغ تحميل (PDF، Word).',
  legalCguTitle: '3. شروط الاستخدام العامة',
  legalCgu31Title: '3.1. الوصول إلى الخدمة',
  legalCgu31Desc: 'يتطلب الوصول إلى الخدمة إنشاء حساب والاشتراك في خطة (خطة Pro أو خطة Lifetime). تكون الخدمة متاحة فور الدفع عبر شريك الدفع الخاص بنا: LemonSqueezy (EUR/USD، بطاقة بنكية دولية، PayPal، Apple Pay، Google Pay).',
  legalCgu32Title: '3.2. الاستخدام المصرح به',
  legalCgu32Desc: 'الخدمة مخصصة للاستخدام الشخصي والمهني المشروع. يلتزم المستخدم بعدم استخدام الخدمة لأغراض غير قانونية أو احتيالية أو تنتهك حقوق الغير.',
  legalCgu33Title: '3.3. الملكية الفكرية',
  legalCgu33Desc: 'اسم "HireNova" والشعار والتصميم والكود المصدري وجميع محتويات الموقع هي ملكية حصرية لـ E-Society 2050. أي إعادة إنتاج أو نسخ أو تعديل أو توزيع أو استخدام للخدمة أو عناصرها دون إذن كتابي مسبق محظور تمامًا ويشكل تقليدًا يعاقب عليه القانون.',
  legalCgu34Title: '3.4. المحتوى المُنشأ',
  legalCgu34Desc: 'السير الذاتية ورسائل التغطية المُنشأة بالذكاء الاصطناعي هي ملكية المستخدم. HireNova لا تدّعي أي حقوق على المحتوى المُنشأ من قبل مستخدميها.',
  legalCgu35Title: '3.5. المدفوعات والاسترداد',
  legalCgu35Desc: 'يتم معالجة المدفوعات من خلال شريك الدفع المرخّص لدينا: LemonSqueezy (EUR/USD). لأي طلب استرداد، يرجى الاتصال بالدعم عبر زر المساعدة على الموقع.',
  legalCgu36Title: '3.6. المسؤولية',
  legalCgu36Desc: 'يقدم HireNova أداة مساعدة في الكتابة. تعتمد جودة النتيجة النهائية على المعلومات المقدمة من المستخدم. لا يمكن تحميل HireNova مسؤولية محتوى المستندات المُنشأة أو استخدامها من قبل المستخدم.',
  legalDataTitle: '4. حماية البيانات الشخصية',
  legalDataIntro: 'وفقًا للتشريع المغربي (القانون 09-08 المتعلق بحماية الأشخاص الطبيعيين فيما يتعلق بمعالجة البيانات الشخصية)، نُعلِم المستخدمين بأن:',
  legalDataBullet1: 'يتم استخدام البيانات المُجمّعة (الاسم، البريد الإلكتروني، معلومات السيرة الذاتية) فقط لتشغيل الخدمة.',
  legalDataBullet2: 'لا يتم بيع البيانات أو مشاركتها مع أطراف ثالثة أبدًا.',
  legalDataBullet3: 'يمكن للمستخدم طلب حذف بياناته في أي وقت بالاتصال بالدعم.',
